/**
 * Demo / offline data helpers.
 *
 * Real scraped data lives in /public/data/*.json (generated by scraper/scrape_cars.py).
 * These helpers fetch that static JSON so the frontend works without a backend.
 */

import type { Brand, CarModel, Generation, DesignDNA, AIAnalysis } from './types'

// ─── Static JSON loaders (used server-side or in useEffect) ──────────────────

export async function fetchBrandData(slug: string): Promise<{
  brand: Brand
  models: CarModel[]
  dna?: DesignDNA
  analysis?: AIAnalysis
} | null> {
  try {
    const res = await fetch(`/data/brands/${slug}.json`)
    if (!res.ok) return null
    const data = await res.json()
    return {
      brand: data as Brand,
      models: (data.models ?? []) as CarModel[],
      dna: data.dna ?? undefined,
      analysis: data.analysis ?? undefined,
    }
  } catch {
    return null
  }
}

export async function fetchModelData(slug: string): Promise<{
  model: CarModel
  generations: Generation[]
  analysis?: AIAnalysis
} | null> {
  try {
    const res = await fetch(`/data/models/${slug}.json`)
    if (!res.ok) return null
    const data = await res.json()
    return {
      model: data as CarModel,
      generations: (data.generations ?? []) as Generation[],
      analysis: data.analysis ?? undefined,
    }
  } catch {
    return null
  }
}

export async function fetchAllBrands(): Promise<Brand[]> {
  try {
    const res = await fetch('/data/brands.json')
    if (!res.ok) return []
    return await res.json()
  } catch {
    return []
  }
}

export async function fetchAllModels(): Promise<CarModel[]> {
  try {
    const res = await fetch('/data/models.json')
    if (!res.ok) return []
    return await res.json()
  } catch {
    return []
  }
}

// ─── React hooks (client-side data fetching with SWR-style caching) ──────────

import { useEffect, useState } from 'react'

type LoadState<T> = { data: T | null; loading: boolean; error: boolean }

export function useDemoBrand(slug: string): LoadState<{ brand: Brand; models: CarModel[]; dna?: DesignDNA; analysis?: AIAnalysis }> {
  const [state, setState] = useState<LoadState<{ brand: Brand; models: CarModel[]; dna?: DesignDNA; analysis?: AIAnalysis }>>({
    data: null, loading: true, error: false,
  })
  useEffect(() => {
    if (!slug) return
    fetchBrandData(slug).then((d) => {
      setState({ data: d, loading: false, error: !d })
    })
  }, [slug])
  return state
}

export function useDemoModel(slug: string): LoadState<{ model: CarModel; generations: Generation[]; analysis?: AIAnalysis }> {
  const [state, setState] = useState<LoadState<{ model: CarModel; generations: Generation[]; analysis?: AIAnalysis }>>({
    data: null, loading: true, error: false,
  })
  useEffect(() => {
    if (!slug) return
    fetchModelData(slug).then((d) => {
      setState({ data: d, loading: false, error: !d })
    })
  }, [slug])
  return state
}

// ─── Legacy sync helpers (kept for backward compat with existing pages) ───────
// These return null — pages should use the async hooks above for real data.

export function getDemoBrand(_slug: string): Brand | undefined { return undefined }
export function getDemoBrandModels(_brandSlug: string): CarModel[] { return [] }
export function getDemoGenerations(_modelSlug: string): Generation[] { return [] }
export function getDemoModel(_modelSlug: string): CarModel | undefined { return undefined }
